script:
if (-not $ACCOUNTS) { throw 'ACCOUNTS is required (csv of samaccountname:password entries)' }
Import-Module ActiveDirectory -ErrorAction Stop
if (-not $PATTERN) { $PATTERN = '^[A-Za-z]+!Acme\d{4}$' }
foreach ($entry in $ACCOUNTS.Split(',')) {
    $pair = $entry.Trim().Split(':', 2)
    if ($pair.Count -ne 2 -or -not $pair[0] -or -not $pair[1]) { throw "bad ACCOUNTS entry '$entry'" }
    $sam = $pair[0]; $pw = $pair[1]
    if ($pw -notmatch $PATTERN) { throw "password for '$sam' does not match the pattern '$PATTERN'" }
    $secure = ConvertTo-SecureString $pw -AsPlainText -Force
    $existing = Get-ADUser -Filter "SamAccountName -eq '$sam'" -ErrorAction Ignore
    if ($existing) {
        Set-ADAccountPassword -Identity $sam -Reset -NewPassword $secure
        Set-ADUser -Identity $sam -Enabled $true -PasswordNeverExpires $true
    } else {
        New-ADUser -Name $sam -SamAccountName $sam -AccountPassword $secure -Enabled $true `
            -DisplayName $sam -Description 'Gavelport records clerk' -PasswordNeverExpires $true
    }
}
Write-Output 'pattern-password accounts planted'
